<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/functions.php';require_once __DIR__ . '/../../auth/guard.php';require_once __DIR__ . '/../../config/database.php';require_once __DIR__ . '/../../includes/module2_helpers.php';requireLogin();
$title='Căn hộ';$keyword=trim((string)($_GET['keyword']??''));$maLoai=(int)($_GET['MaLoai']??0);$trangThai=(string)($_GET['TrangThai']??'');$page=max(1,(int)($_GET['page']??1));$perPage=(int)($_GET['perPage']??10);$perPage=in_array($perPage,[10,20,50],true)?$perPage:10;$offset=($page-1)*$perPage;$where=[];$params=[];if($keyword!==''){$where[]='(c.SoPhong LIKE :kw OR CAST(c.MaCanHo AS CHAR) LIKE :kw)';$params[':kw']="%$keyword%";}if($maLoai>0){$where[]='c.MaLoai=:loai';$params[':loai']=$maLoai;}if(in_array($trangThai,['Trống','Đang thuê','Bảo trì'],true)){$where[]='c.TrangThai=:tt';$params[':tt']=$trangThai;}$ws=$where?'WHERE '.implode(' AND ',$where):'';$s=$pdo->prepare("SELECT COUNT(*) FROM CanHo c $ws");$s->execute($params);$total=(int)$s->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));$s=$pdo->prepare("SELECT c.*,l.TenLoai,(SELECT a.DuongDan FROM CanHo_Anh a WHERE a.MaCanHo=c.MaCanHo AND a.LaAnhDaiDien=1 LIMIT 1) AnhDaiDien FROM CanHo c JOIN LoaiCanHo l ON l.MaLoai=c.MaLoai $ws ORDER BY c.MaCanHo DESC LIMIT :limit OFFSET :offset");foreach($params as $k=>$v)$s->bindValue($k,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$s->bindValue(':limit',$perPage,PDO::PARAM_INT);$s->bindValue(':offset',$offset,PDO::PARAM_INT);$s->execute();$items=$s->fetchAll();$types=$pdo->query('SELECT MaLoai,TenLoai FROM LoaiCanHo ORDER BY TenLoai')->fetchAll();require_once __DIR__ . '/../../includes/header.php';
?><div class="page-header"><div><h1>Căn hộ</h1><p class="text-muted">Nhân viên được xem và cập nhật thông tin nghiệp vụ.</p></div></div><form method="get" class="filter-card"><div class="form-group grow"><label>Tìm mã/số phòng</label><input name="keyword" value="<?=e($keyword)?>"></div><div class="form-group"><label>Loại</label><select name="MaLoai"><option value="0">Tất cả</option><?php foreach($types as $t):?><option value="<?=$t['MaLoai']?>" <?=$maLoai===(int)$t['MaLoai']?'selected':''?>><?=e($t['TenLoai'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Trạng thái</label><select name="TrangThai"><option value="">Tất cả</option><?php foreach(['Trống','Đang thuê','Bảo trì'] as $s):?><option <?=$trangThai===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><button class="btn btn-secondary">Lọc</button></form><div class="table-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Ảnh</th><th>Số phòng</th><th>Loại</th><th>Diện tích</th><th>Giá thuê</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="7" class="empty-state">Không có dữ liệu.</td></tr><?php else:foreach($items as $item):?><tr><td><?php if($item['AnhDaiDien']):?><img class="thumb" src="<?=e(appUrl($item['AnhDaiDien']))?>"><?php else:?><div class="thumb no-image">🏢</div><?php endif;?></td><td><strong><?=e($item['SoPhong'])?></strong></td><td><?=e($item['TenLoai'])?></td><td><?=number_format((float)$item['DienTich'],2,',','.')?> m²</td><td><?=formatMoney($item['GiaThue'])?></td><td><?=renderStatusBadge($item['TrangThai'])?></td><td><a class="btn btn-sm btn-light" href="detail.php?id=<?=$item['MaCanHo']?>">Xem</a><a class="btn btn-sm btn-secondary" href="edit.php?id=<?=$item['MaCanHo']?>">Sửa</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?=module2_pagination($page,$totalPages,['keyword'=>$keyword,'MaLoai'=>$maLoai,'TrangThai'=>$trangThai,'perPage'=>$perPage])?><?php require_once __DIR__ . '/../../includes/footer.php'; ?>